import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Forecast } from '../types'
import { bar, chart, compact, growth, percentOf, push, weather } from './forecast'

const forecast = atom({ plugin: 'token-weather', key: 'forecast' } as const, null)

// Record where the context stands after a finished turn. A compaction
// shrinks the context, so the delta can go negative; that is shown as ▼.
async function record($: EngineInterface) {
  const { context } = await $.session.usage()
  await update($, forecast, (prev): Forecast => {
    const history = prev?.history ?? []
    if (context.tokens === undefined) {
      return { history, tokens: null, window: context.window, delta: null }
    }
    const before = history[history.length - 1] ?? 0
    return {
      history: push(history, context.tokens),
      tokens: context.tokens,
      window: context.window,
      delta: context.tokens - before,
    }
  })
}

export const register: Register = on => {
  // Seed from the session's last response so a resumed session isn't blank.
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    await record($)
    return result
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    // A subagent's turn is its own loop; the forecast follows the main one.
    if (e.agentId === undefined) await record($)
    return result
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    // Keep what a plugin beneath drew and stack ours on top.
    const below = await next(e)
    const f = await read($, forecast)
    if (e.props.hasSurvey || f === null || f.tokens === null) return below

    const { Box, Text, Button } = $.ui.resolve(e)
    const percent = percentOf(f.tokens, f.window)
    const w = weather(percent)
    const [full, empty] = bar(percent, 24)
    const g = f.delta === null ? null : growth(f.delta)

    const band = (
      <Box flexDirection="row">
        <Text color={w.color} bold>
          {w.icon} {w.word}
        </Text>
        <Text dimColor> · </Text>
        <Text bold>{percent}%</Text>
        <Text> </Text>
        <Text color={w.color} bold>
          {full}
        </Text>
        <Text color="gray">{empty}</Text>
        <Text dimColor>
          {' '}
          {compact(f.tokens)} / {compact(f.window)}
        </Text>
        <Text dimColor> · </Text>
        <Text color={w.color}>{chart(f.history, f.window)}</Text>
        {g === null ? null : (
          <Text dimColor>
            {' · '}
            {g.arrow} {g.text}
          </Text>
        )}
        {/* One click compacts, no /compact typed. Hidden mid-turn, when a
            compaction can't run. Claude terracotta, like Gaurav's Tools. */}
        {e.props.isWorking ? null : (
          <Box key="tw-compact-box" marginLeft={2} paddingX={1} backgroundColor="#d97757">
            <Button
              key="tw-compact"
              label="⇣ Compact"
              plain
              hover={{ color: '#ffffff', backgroundColor: '#e8906f', bold: true }}
              onPress={() => $.session.compact()}
            />
          </Box>
        )}
      </Box>
    )

    return below ? (
      <Box flexDirection="column">
        {band}
        {below}
      </Box>
    ) : (
      band
    )
  })
}

