export const TURNS = 12

const BARS = '▁▂▃▄▅▆▇█'

export type Weather = { icon: string; word: string; color: string }

export function weather(percent: number): Weather {
  if (percent >= 90) return { icon: '↯', word: 'Compact soon', color: 'red' }
  if (percent >= 75) return { icon: '☇', word: 'Storm', color: 'magenta' }
  if (percent >= 50) return { icon: '☂', word: 'Showers', color: 'blue' }
  if (percent >= 25) return { icon: '☁', word: 'Cloudy', color: 'cyan' }
  return { icon: '☀', word: 'Clear', color: 'yellow' }
}

export function percentOf(tokens: number, window: number): number {
  return window <= 0 ? 0 : Math.max(0, Math.min(100, Math.round((tokens / window) * 100)))
}

// 134400 -> "134.4k", 200000 -> "200k", 1000000 -> "1M", 850 -> "850".
export function compact(n: number): string {
  const abs = Math.abs(n)
  if (abs >= 1_000_000) return trim(abs / 1_000_000) + 'M'
  if (abs >= 1_000) return trim(abs / 1_000) + 'k'
  return String(Math.round(abs))
}

function trim(x: number): string {
  return x.toFixed(1).replace(/\.0$/, '')
}

// One block per turn, scaled to the window so the chart reads the same as the percentage.
export function chart(history: number[], window: number): string {
  return history
    .map(t => {
      const level = window <= 0 ? 0 : Math.min(1, Math.max(0, t / window))
      return BARS[Math.min(BARS.length - 1, Math.floor(level * BARS.length))]
    })
    .join('')
}

export function growth(delta: number): { arrow: string; text: string } {
  const sign = delta < 0 ? '-' : '+'
  return { arrow: delta < 0 ? '▼' : '▲', text: `${sign}${compact(delta)} last turn` }
}

export function push(history: number[], tokens: number): number[] {
  return [...history, tokens].slice(-TURNS)
}

// Eighths of a cell, so the fill's edge moves smoothly instead of a whole cell at a time.
const EIGHTHS = ['', '▏', '▎', '▍', '▌', '▋', '▊', '▉']

// A fill gauge for the percentage: solid full-height blocks on a shaded track.
// Any use at all shows at least an eighth of a cell.
export function bar(percent: number, width: number): [string, string] {
  const p = Math.max(0, Math.min(100, percent))
  const eighths = p === 0 ? 0 : Math.max(1, Math.round((p / 100) * width * 8))
  const whole = Math.floor(eighths / 8)
  const part = EIGHTHS[eighths % 8]
  const used = whole + (part ? 1 : 0)
  return ['█'.repeat(whole) + part, '░'.repeat(width - used)]
}

