export type Forecast = {
  /** Input tokens in the context after each of the last turns, oldest first (at most 12). */
  history: number[]
  /** Tokens in the context now; null until a response of the live window reports one. */
  tokens: number | null
  /** The model's context window, in tokens. */
  window: number
  /** What the last turn added (negative after a compaction); null before two readings. */
  delta: number | null
}

declare module 'claude-code' {
  interface PluginState {
    'token-weather': { forecast: Forecast | null }
  }
}
